    ('0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'Quiz — Invariables, antéposés, et dans le bon ordre', 'Anglais', '2de', 'Les adjectifs qualificatifs', '49250910-b279-5bba-8bcd-fddae6fbcfbb'::uuid),
    ('bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Quiz — Be, have, do — trois rôles à ne pas confondre', 'Anglais', '2de', 'Les verbes lexicaux et les auxiliaires', '1ae48e82-580e-5835-9d49-aa2e0d75399a'::uuid),
