    ('e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, 'Quiz — Give up, look after — la particule change tout', 'Anglais', '2de', 'Les verbes à particule et les verbes prépositionnels', 'daf62bbc-5a15-541f-8f02-37567502d7d4'::uuid),
    ('b429896b-e68c-55c1-abeb-73c34c0d3d8e'::uuid, 'Quiz — To do ou doing : le verbe choisit', 'Anglais', '2de', 'Infinitif et gérondif', '61f254db-7751-5810-9157-4568d7d979a4'::uuid),
    ('f28bbf7b-31e6-5e49-9b4d-22e6669ad27e'::uuid, 'Quiz — Comment, quand, à quel point', 'Anglais', '2de', 'Les adverbes', 'eb13dc15-89d2-592b-bd5f-4e1375944611'::uuid),
    ('c4a87bda-7274-51d3-aaeb-fa572c3ed4b5'::uuid, 'Quiz — Ce qui est vrai en général, ce qui se passe maintenant', 'Anglais', '2de', 'Le présent simple et le présent en BE + -ING', 'd3288f16-1cc3-532e-be89-c67b9af7fd5c'::uuid),
    ('90068a71-02c9-59f8-a57b-c0f63a763480'::uuid, 'Quiz — Le passé coupé du présent', 'Anglais', '2de', 'Le prétérit simple et le prétérit BE + -ING', '05caa486-1e6f-5cca-a7f3-73189d60ac7a'::uuid),
    ('963eaed4-181c-57d1-8e22-e010199a303c'::uuid, 'Quiz — Le passé qui compte encore aujourd’hui', 'Anglais', '2de', 'Le present perfect et le present perfect BE + -ING', '46db0e26-c6d2-5fcd-a25b-e6ce6d012c36'::uuid),
    ('ecaf4cdc-2f8d-5580-a247-0ef26a9f2c22'::uuid, 'Quiz — Le passé avant le passé', 'Anglais', '2de', 'Le past perfect et le past perfect BE + -ING', 'd73f582b-85b1-5ff8-b25f-f88a12cc35f0'::uuid),
    ('42f64493-b53c-5f27-86a2-c9a7f0778935'::uuid, 'Quiz — Will, be going to, et l’irréel', 'Anglais', '2de', 'Exprimer le futur et le conditionnel', 'b2bf74ca-3fa8-5b76-8571-729251aa91bd'::uuid),
    ('90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, 'Quiz — L’auxiliaire d’abord', 'Anglais', '2de', 'Les questions', '647d3781-3683-504a-88ed-c6ee1bcadb80'::uuid),
    ('00445851-5235-5624-a323-6a7929e96b9b'::uuid, 'Quiz — What a…! How…!', 'Anglais', '2de', 'La phrase exclamative', '04a71030-ae93-5fdc-a048-21d30df94b8b'::uuid),
    ('963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Quiz — Plus, moins, autant — et le plus', 'Anglais', '2de', 'Le comparatif et le superlatif', '3dee66a3-bb26-567a-a39f-95a528ac444f'::uuid),
    ('fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Quiz — Relatives, complétives, circonstancielles', 'Anglais', '2de', 'Les subordonnées', '3b5ba115-feb6-5eed-b9ea-04d4f0791cb2'::uuid),
    ('260031d5-2c4d-5f47-a033-5366020445ad'::uuid, 'Quiz — For, since, ago, during — chacun son rôle', 'Anglais', '2de', 'Exprimer la temporalité et la durée', 'd55fa1fa-2448-5148-b927-7e0a63ed8dcb'::uuid),
    ('b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, 'Quiz — Because, since, so that, in order to', 'Anglais', '2de', 'Exprimer la cause et le but', 'd6b5c1ac-173a-5938-86f6-dd74866c9d1d'::uuid),
    ('ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, 'Quiz — If, unless, although, whereas', 'Anglais', '2de', 'Exprimer la condition, la concession et l’opposition', '4f4a5374-bc64-59ba-9308-d3a70352b329'::uuid),
    ('4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, 'Quiz — Used to, would, be used to', 'Anglais', '2de', 'Exprimer l’habitude', 'c2edaec3-1271-5897-bd56-f1a2044555cf'::uuid),
    ('b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, 'Quiz — Make, have, get, let — la causation', 'Anglais', '2de', 'Faire faire quelque chose à quelqu’un', '70c49ef8-962a-5202-ada8-591d838d1491'::uuid),
    ('99ab7429-d1b1-5804-bb06-a5490c93fd33'::uuid, 'Quiz — Be + participe passé', 'Anglais', '2de', 'La voix passive', '11cb726a-4aa7-5ed6-8974-4e2865cbbf7d'::uuid),
    ('89f88408-b91a-5ff0-8528-689be419accc'::uuid, 'Quiz — Rapporter des paroles', 'Anglais', '2de', 'Le discours indirect', '0b65327d-5052-5bba-9c7b-9845756228fe'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('0d52bd4c-6ad4-529f-a842-c48a191828d0'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'Pourquoi écrit-on « an hour » et non « a hour » ?', 'mcq', '["Parce que le h ne se prononce pas","Parce que « hour » est un nom abstrait","Parce que le mot commence par une consonne écrite","Parce que c’est une exception sans règle"]'::jsonb, 0, 'Le choix a/an dépend du SON initial, pas de la lettre.', 1),
    ('5cafa2ea-103b-5bcb-8183-641e0c73bf8f'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'On écrit « a university » et non « an university ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot commence par le son /j/ (« you »), donc « a ».', 2),
    ('7649abe1-f1e9-5ca1-9c9b-82f62538265a'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'Comment traduit-on « La vie est dure » ?', 'mcq', '["Life is hard","The life is hard","A life is hard","The life is the hard"]'::jsonb, 0, 'Un nom pris au sens général ne prend pas d’article en anglais.', 3),
    ('f2e4bd6a-c0d9-5586-9437-bc85b9b11e05'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, '« The » s’emploie devant les noms de pays au pluriel comme *the Netherlands*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De même *the United States*, *the Philippines*.', 4),
    ('cc574076-a553-5be8-8a12-c52d65da747f'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'Le génitif de « les sacs des étudiants » s’écrit…', 'mcq', '["the students’ bags","the students’s bags","the student’s bags","the bags of students"]'::jsonb, 0, 'Un pluriel déjà en -s ne prend que l’apostrophe.', 5),
    ('f9ec0d8c-e7c6-5556-9e09-31cb3630a4bc'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'Dans « his sister », le possessif s’accorde avec…', 'mcq', '["Le possesseur","L’objet possédé","Le verbe","Le sujet de la phrase suivante"]'::jsonb, 0, 'C’est un frère ou une sœur DE LUI : *his*, quel que soit le genre de « sister ».', 6),
    ('c8783ea6-9206-5b17-8e32-374b331a260c'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, '« These » désigne ce qui est éloigné dans l’espace ou le temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*These* est proche ; *those* est éloigné.', 7),
    ('3cdb406c-04f3-5b0b-8b19-043516bc1c01'::uuid, 'b4017af6-d991-5285-9bd0-fcafe6ab3aa5'::uuid, 'Devant un superlatif, on emploie…', 'mcq', '["the","a","an","aucun article"]'::jsonb, 0, '*She is the best student in the class.*', 8),
    ('462afad3-f5ee-5c67-b9b8-359ccc1bceed'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, 'Quel quantifieur s’emploie avec un indénombrable ?', 'mcq', '["much","many","a few","several"]'::jsonb, 0, '*Much money*, mais *many books*.', 1),
    ('6a2f81eb-a89d-56f3-936c-795c984a9735'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, '« A few friends » signifie « très peu d’amis, presque aucun ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*A few* est positif (« quelques ») ; c’est *few* qui est négatif.', 2),
    ('2fef4303-e124-5d24-bc1b-6921e9cc8ab6'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, 'Comment traduit-on « un conseil » ?', 'mcq', '["A piece of advice","An advice","A advice","One advice"]'::jsonb, 0, '*Advice* est indénombrable : il passe par *a piece of*.', 3),
    ('4e9ac752-e0e6-550f-8d5a-df14df923a84'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, 'Dans une question, on emploie normalement…', 'mcq', '["any","some","much of","a lot"]'::jsonb, 0, '*Have you got any money?* — *some* reste possible pour une offre.', 4),
    ('0b9f7752-44b2-5fba-81aa-c3189289e853'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, '« The news is good » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*News* est un indénombrable singulier malgré son -s.', 5),
    ('fc672ece-93d3-5765-a958-9a6b96845e95'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, 'Où se place « enough » avec un adjectif ?', 'mcq', '["Après l’adjectif : old enough","Avant l’adjectif : enough old","En fin de phrase uniquement","Avant le verbe"]'::jsonb, 0, 'Mais devant un nom il précède : *enough time*.', 6),
    ('235fecae-fbe3-5791-9860-202f9c2497a4'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, '« Too much homework » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Homework* est indénombrable, donc *much* et pas *many*.', 7),
    ('86dd32e1-c01b-5841-bdbf-db8bedaefdb7'::uuid, '704bfd6e-1182-5a55-8a3e-a8c0a3fe4b3c'::uuid, '« Any student can apply » signifie…', 'mcq', '["N’importe quel étudiant peut postuler","Aucun étudiant ne peut postuler","Quelques étudiants postulent","Tous les étudiants ont postulé"]'::jsonb, 0, 'À l’affirmative, *any* prend le sens de « n’importe lequel ».', 8),
    ('b4cc07d0-2a3c-5a75-85cc-9f5e34b5c00b'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'Comment traduit-on « de grands bâtiments » ?', 'mcq', '["Tall buildings","Talls buildings","Buildings tall","Tall buildingses"]'::jsonb, 0, 'L’adjectif est invariable et se place avant le nom.', 1),
    ('cfc4ae85-9c2c-5501-b3c0-478f90db6019'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, '« I am boring » signifie…', 'mcq', '["Je suis ennuyeux","Je m’ennuie","Je suis fatigué","Je suis pressé"]'::jsonb, 0, 'Pour « je m’ennuie », il faut *I am bored*.', 2),
    ('bbf0336d-b0b1-503a-9ac2-f14bc1e8cb91'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'L’adjectif en -ing décrit ce qui provoque l’émotion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Interesting* provoque, *interested* ressent.', 3),
    ('ee017870-8d45-5dc1-8dcf-26a395c0412b'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'Quel est l’ordre correct ?', 'mcq', '["A big red Italian car","A red big Italian car","An Italian red big car","A red Italian big car"]'::jsonb, 0, 'Taille, puis couleur, puis origine.', 4),
    ('7429bf84-3d38-59d3-9ee4-602ea6b95b48'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'Après « seem », l’adjectif reste attribut du sujet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*She seems happy* — comme après *be*, *look*, *feel*.', 5),
    ('84ce9dd1-4cad-54a1-b663-2e1c031cf28d'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, '« The unemployed » désigne…', 'mcq', '["Les chômeurs, comme groupe","Un chômeur","Le chômage","Le licenciement"]'::jsonb, 0, '*The* + adjectif désigne l’ensemble d’un groupe.', 6),
    ('cff0e993-d56a-5165-bc49-d9d08178b769'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, '« The rich is getting richer » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’adjectif substantivé est pluriel : *the rich ARE getting richer*.', 7),
    ('94c44859-26c6-5980-a6e7-ae333cc93e7b'::uuid, '0a2b7dfe-ead2-5045-8986-70da1561a103'::uuid, 'Un adjectif anglais s’accorde en nombre avec le nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est toujours invariable, quelle que soit sa place.', 8),
    ('1cd683e3-387e-5cf4-81a6-20ac862ed8f2'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Dans « The house was built in 1920 », « was » est…', 'mcq', '["Un auxiliaire du passif","Un verbe lexical signifiant « être »","Un modal","Un auxiliaire du present perfect"]'::jsonb, 0, '*Be* + participe passé = voix passive.', 1),
    ('1de0e53e-5635-5907-b03e-b25ace1e9d40'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Comment traduit-on « J’ai froid » ?', 'mcq', '["I am cold","I have cold","I have got cold","It makes me cold"]'::jsonb, 0, 'L’anglais emploie *be* là où le français emploie « avoir ».', 2),
    ('cdcd5899-08f3-529d-be24-d06d7ded4001'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, '« Like you tea? » est une question correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans auxiliaire, il faut en fabriquer un : *Do you like tea?*', 3),
    ('6572d634-14e8-5df6-b701-77e5c4da405b'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Dans « I DO like it », l’auxiliaire sert à…', 'mcq', '["Insister","Poser une question","Nier","Former un passé"]'::jsonb, 0, 'C’est l’emphase, souvent pour contredire.', 4),
    ('e4a90888-931d-50d6-b0a9-e763a86f8d96'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Dans « I have a car », « have » est un verbe lexical.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il signifie « posséder » et n’aide aucun autre verbe.', 5),
    ('2383fd20-a2a6-53e0-bcff-553a36d5747b'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Quel élément porte la négation dans une phrase anglaise ?', 'mcq', '["L’auxiliaire","Le verbe lexical","Le sujet","Le complément"]'::jsonb, 0, '*I do not know*, *she has not finished*.', 6),
    ('be5a9be2-84e5-54a5-bc77-c75321a3e25c'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, '« Have breakfast » signifie « posséder un petit-déjeuner ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ici *have* signifie « prendre ».', 7),
    ('f19599fb-f72a-5cf5-9b84-bc39d704c685'::uuid, 'bd13c861-1a02-5031-a964-ae6487a6b5bc'::uuid, 'Dans un question tag, on reprend…', 'mcq', '["L’auxiliaire de la phrase","Le verbe lexical","Le sujet seul","Un mot interrogatif"]'::jsonb, 0, '*You like it, don’t you?* — l’auxiliaire est fabriqué si besoin.', 8),
    ('f2816105-3ac3-5d67-8a7c-f603c595372e'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, 'Quelle forme suit un modal ?', 'mcq', '["La base verbale sans TO","L’infinitif avec TO","Le participe présent","Le prétérit"]'::jsonb, 0, '*He can swim*, jamais *he can to swim*.', 1),
    ('103173f8-7118-59cb-b4f8-1c6f05bf93ed'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« He cans swim » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un modal ne prend jamais de -s à la 3e personne.', 2),
    ('5db9e0d4-b692-5e05-99a4-8b455a743d73'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« You mustn’t go » signifie…', 'mcq', '["Tu ne dois pas y aller : c’est interdit","Tu n’es pas obligé d’y aller","Tu devrais y aller","Tu pourras y aller"]'::jsonb, 0, 'L’absence d’obligation, c’est *you don’t have to go*.', 3),
    ('ff3a7443-01c1-510d-a4c9-bb76f3602863'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« He must be tired » exprime ici…', 'mcq', '["Une déduction","Une obligation","Une permission","Une capacité passée"]'::jsonb, 0, 'C’est la valeur épistémique de *must*.', 4),
    ('edab606d-8f8f-5562-87e0-a9119f39024a'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« He will can come » est une forme correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Deux modaux ne se suivent pas : *he will be able to come*.', 5),
    ('95e61238-61c6-5cea-b457-702b05ae709e'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« She should have called » exprime…', 'mcq', '["Un reproche sur le passé","Une obligation future","Une capacité","Une permission"]'::jsonb, 0, 'Modal + *have* + participe passé porte un regard sur le passé.', 6),
    ('efd392ff-8db1-59df-a4aa-e3c60d1986f4'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, 'Quelle différence entre « must » et « have to » ?', 'mcq', '["Must vient du locuteur, have to des circonstances","Must est toujours passé","Have to est un modal","Aucune différence"]'::jsonb, 0, 'D’où *I must stop smoking* (ma décision) vs *I have to work late* (on m’y oblige).', 7),
    ('acbbb8c3-0c37-5718-9035-3d4e61dc0006'::uuid, 'fe70e506-a30b-5eff-aa31-c158eabe40d5'::uuid, '« It might rain » exprime une possibilité incertaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*May* et *might* marquent l’éventualité.', 8),
    ('8fd3dd5a-75cf-56a1-9cda-8712d8f35e16'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, 'Que signifie « give up » ?', 'mcq', '["Abandonner","Donner","Se lever","Rendre visite"]'::jsonb, 0, 'La particule change complètement le sens du verbe.', 1),
    ('6403efdb-2a1e-526b-a180-487c3af70b2e'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, '« Turn on it » est correct pour « allume-la ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un pronom s’intercale obligatoirement : *turn it on*.', 2),
    ('167c1818-3549-5b6f-93e7-95014d238a33'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, 'Que signifie « look after » ?', 'mcq', '["S’occuper de","Chercher","Regarder","Ressembler à"]'::jsonb, 0, '*Look for* = chercher, *look at* = regarder.', 3),
    ('61f61bbc-c598-585b-b61f-09ab8a27a376'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, 'Dans un verbe prépositionnel, le complément peut s’intercaler.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La préposition est inséparable : *listen to the radio*.', 4),
    ('16378145-73c0-5418-a09a-2c40db2cf222'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, '« I look forward to hearing from you » se termine par un gérondif parce que…', 'mcq', '["« to » y est une préposition, pas la marque de l’infinitif","C’est une exception","Le verbe est irrégulier","La phrase est au passif"]'::jsonb, 0, 'Après une préposition, l’anglais met toujours la forme en -ING.', 5),
    ('fae14dc3-7e83-56f2-8664-49c315cbfbee'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, '« Who are you waiting for? » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La préposition peut rester en fin de phrase, contrairement au français.', 6),
    ('bbcb19b6-49ff-53d6-b0bf-fce798039d8f'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, 'Que signifie « put off » ?', 'mcq', '["Reporter","Poser","Éteindre le feu","Se déshabiller"]'::jsonb, 0, '*The meeting was put off until Monday.*', 7),
    ('3325b49e-ab6d-55de-bf4d-45770ba8c8bf'::uuid, 'e1a612c1-4491-5f70-8a6d-c96f5d9f9d49'::uuid, '« Look up a word » signifie…', 'mcq', '["Chercher un mot dans un dictionnaire","Lever les yeux vers un mot","Épeler un mot","Souligner un mot"]'::jsonb, 0, 'Encore une particule qui refait le sens du verbe.', 8),
