    ('d1ed0e4b-3347-5360-ba21-abff6a3c53bf'::uuid, 'c4a87bda-7274-51d3-aaeb-fa572c3ed4b5'::uuid, '« He is always complaining » ajoute une nuance…', 'mcq', '["D’agacement","De politesse","De doute","De regret"]'::jsonb, 0, '*Always* + -ING marque l’exaspération.', 4),
