    ('8df2e0a9-b809-535c-b81f-0d0efa7ae8f8'::uuid, '90068a71-02c9-59f8-a57b-c0f63a763480'::uuid, '« I didn’t went » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Did* porte déjà le passé : *I didn’t go.*', 2),
