    ('d774a8d1-b99c-58e7-ac73-e5710ccea91c'::uuid, '963eaed4-181c-57d1-8e22-e010199a303c'::uuid, 'Comment se forme le present perfect ?', 'mcq', '["have/has + participe passé","had + participe passé","be + -ing","did + base verbale"]'::jsonb, 0, '*I have finished*, *she has gone*.', 1),
