    ('bdd42b9f-62fd-523d-8bd8-181ee3c4f66a'::uuid, 'ecaf4cdc-2f8d-5580-a247-0ef26a9f2c22'::uuid, 'Le past perfect s’emploie aussi dans l’irréel du passé après « if ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*If I had known, I would have come.*', 6),
