    ('e54df58d-8138-5a21-8007-67e654fa7820'::uuid, '90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, 'Quel est l’ordre correct ?', 'mcq', '["Where does she live?","Where she lives?","Where does she lives?","Where lives she?"]'::jsonb, 0, 'Auxiliaire + sujet + base verbale.', 1),
