    ('16b836a1-4f69-541c-85e6-c652f91a4e9c'::uuid, '90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, 'Le tag de « You’re French » est…', 'mcq', '["aren’t you?","are you?","don’t you?","isn’t it?"]'::jsonb, 0, 'La polarité s’inverse et l’auxiliaire se reprend.', 5),
    ('016fe176-602f-5fbb-953f-7f53dc74154d'::uuid, '90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, 'Dans une question, le verbe lexical reste à la base verbale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Does she live*, jamais *does she lives*.', 6),
    ('81db63da-90f9-5da4-addd-d9dad5755bcf'::uuid, '90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, '« Which » s’emploie plutôt quand…', 'mcq', '["Le choix est limité à un ensemble connu","On ignore tout de l’ensemble","On interroge sur une personne","On interroge sur un lieu"]'::jsonb, 0, '*Which of these two do you prefer?*', 7),
    ('1ab3e5f3-55a3-5f78-adf2-2d77748e5335'::uuid, '90ab731b-e6ee-5171-b5d1-137faf218241'::uuid, 'Le tag de « He can’t swim » est « can he? ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Phrase négative → tag affirmatif.', 8),
    ('8760bb99-9d2a-5ab3-b4ae-3caf5b6dc31d'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, 'Comment traduit-on « Quelle belle journée ! » ?', 'mcq', '["What a beautiful day!","How a beautiful day!","What beautiful day!","How beautiful day!"]'::jsonb, 0, '*What* + nom, avec l’article au singulier dénombrable.', 1),
    ('075cf01d-c117-5d2f-80f4-0c9e874447d7'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, '« What terrible weather! » est correct sans article.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Weather* est indénombrable : pas de *a*.', 2),
    ('bf2da7bb-245a-5586-8758-9e3ccb967e9b'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, '« How » introduit…', 'mcq', '["Un adjectif ou un adverbe","Un nom","Un verbe conjugué","Un sujet"]'::jsonb, 0, '*How strange!*, *How beautifully she sings!*', 3),
    ('2299ff08-9798-5a26-bb32-0bb0e3d09bcd'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, 'Dans une exclamative, on inverse sujet et verbe comme dans une question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’ordre reste normal : *What a mess this is!*', 4),
    ('e64354a5-1573-522c-9078-cd40f922666b'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, 'Quelle forme est correcte ?', 'mcq', '["It’s such a mess","It’s so a mess","It’s such mess","It’s so mess"]'::jsonb, 0, '*Such* + groupe nominal, *so* + adjectif.', 5),
    ('451406e3-0aec-5416-b92b-3c1d25850b24'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, '« How kind of you to come! » est une exclamation correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*How* + adjectif, complété par un infinitif.', 6),
    ('515595bb-bad0-5663-8350-9b15d7e54278'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, '« What lovely flowers! » ne prend pas d’article parce que…', 'mcq', '["Le nom est au pluriel","Le nom est abstrait","L’adjectif commence par une consonne","C’est une exception"]'::jsonb, 0, '*A / an* n’existe qu’au singulier.', 7),
    ('204eeb6b-5f67-5825-97b0-f24379757251'::uuid, '00445851-5235-5624-a323-6a7929e96b9b'::uuid, '« It’s so cold! » exprime une exclamation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*So* + adjectif est la tournure courante à l’oral.', 8),
    ('c094d4c8-cf6e-53f1-8f5f-9dbfb4c93897'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Quel est le comparatif de « expensive » ?', 'mcq', '["more expensive than","expensiver than","the most expensive","as expensive"]'::jsonb, 0, 'Adjectif long : *more … than*.', 1),
    ('e13845d3-7fb8-5b53-abc6-a31713e3b0c5'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, '« More taller » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule marque de comparatif à la fois.', 2),
    ('eb0389c4-29f4-5052-9e2f-47f007d46e61'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Quel est le superlatif de « good » ?', 'mcq', '["the best","the goodest","the better","the most good"]'::jsonb, 0, 'Irrégulier : *good – better – the best*.', 3),
    ('4070954a-ef1b-527e-8d60-6bf08bf536c6'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, '« Big » fait son comparatif en…', 'mcq', '["bigger","biger","more big","biggest"]'::jsonb, 0, 'La consonne finale double après une voyelle courte.', 4),
    ('c85298fc-0966-54bb-9cec-e2642a7e297e'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, '« As tall as » exprime l’égalité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et *not as tall as* l’infériorité.', 5),
    ('ed658c94-4110-5eb9-8b32-a9aab6921393'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Comment traduit-on « Plus je lis, plus je comprends » ?', 'mcq', '["The more I read, the more I understand","More I read, more I understand","The most I read, the most I understand","More and more I read"]'::jsonb, 0, 'Structure *the more … the more*.', 6),
    ('b2448173-e510-525a-bd38-c492c0b5adc5'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Le superlatif s’emploie sans article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il prend toujours *the* : *the tallest building*.', 7),
    ('df028862-1d2d-5a48-8aa4-2347ae67c20f'::uuid, '963dde70-4289-50eb-9afd-548c4f10d210'::uuid, 'Quel est le comparatif de « bad » ?', 'mcq', '["worse","badder","more bad","worst"]'::jsonb, 0, '*Bad – worse – the worst*.', 8),
    ('f9fddd89-d30a-5798-9477-2e548a94761c'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Quel relatif exprime la possession ?', 'mcq', '["whose","which","who","whom"]'::jsonb, 0, '*The student whose bag was stolen.*', 1),
    ('77f3dd16-f0bd-5be9-98d5-653ea5be9562'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Une relative appositive peut être introduite par « that ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Entre virgules, on emploie *who* ou *which*, jamais *that*.', 2),
    ('598baf79-b03a-5b48-a51e-b31b835cb87d'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, '« The book I read yesterday » est correct sans relatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le relatif complément peut s’effacer.', 3),
    ('6d8096f7-cb23-5d68-b0f6-195be0a74c44'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Dans « The man who called is my uncle », la relative…', 'mcq', '["Identifie de quel homme on parle","Ajoute une information accessoire","Exprime une cause","Exprime une condition"]'::jsonb, 0, 'Relative déterminative : pas de virgule.', 4),
    ('0ab3019a-4063-57a7-8a80-ca3cd1e62691'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Quel verbe exige un complément de personne ?', 'mcq', '["tell","say","think","hope"]'::jsonb, 0, '*Tell me*, mais *say to me*.', 5),
    ('b960c2d6-5f95-5c26-bd9b-7cc4531d14a0'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, '« Although » introduit…', 'mcq', '["Une concession","Une cause","Un but","Une condition"]'::jsonb, 0, '*Although it was raining, we went out.*', 6),
    ('4185c27e-0f15-56ba-ac8f-fefad6f0c62e'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, 'Après « until », on emploie le futur avec « will ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme après *when* et *if* : présent obligatoire.', 7),
    ('a02da589-7de1-552a-a7c5-71730859314a'::uuid, 'fb92d00c-4e54-5e64-8af7-98c65b1c833b'::uuid, '« So that » introduit…', 'mcq', '["Un but","Une conséquence datée","Une comparaison","Une opposition"]'::jsonb, 0, '*He left early so that he could catch the train.*', 8),
    ('2d91beea-1078-5fea-b67b-9ae3810f8b97'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, 'Lequel introduit un point de départ ?', 'mcq', '["since","for","ago","during"]'::jsonb, 0, '*Since 2019*, *since Monday*.', 1),
    ('fbd2281d-a82c-5289-8845-59894f8652f7'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, '« I have lived here since six years » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une durée appelle *for* : *for six years*.', 2),
    ('e225eee1-ea7b-5daf-bfee-da5ce096264c'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, '« Ago » s’emploie avec…', 'mcq', '["Le prétérit","Le present perfect","Le présent","Le past perfect"]'::jsonb, 0, '*I met her three days ago.*', 3),
    ('a58e9402-a912-5789-bf3c-f96457489d44'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, 'Quelle forme est correcte ?', 'mcq', '["During the meeting","During we were talking","While the meeting","While of the meeting"]'::jsonb, 0, '*During* + nom, *while* + proposition.', 4),
    ('a8684a0b-a918-51b8-a2e6-fcb8845f488f'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, '« By Friday » signifie « jusqu’à vendredi ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela signifie « d’ici vendredi, au plus tard » ; « jusqu’à » se dit *until*.', 5),
    ('55e90a7e-c334-5660-a915-e4f6b5ab5bab'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, '« In two weeks » signifie…', 'mcq', '["Dans deux semaines","Il y a deux semaines","Pendant deux semaines","Depuis deux semaines"]'::jsonb, 0, 'Pour « pendant », il faudrait *for*.', 6),
    ('27236a7d-c4cf-56c4-8240-ac61c15bd0d1'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, '« Since » va le plus souvent avec le present perfect.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il relie un point du passé au présent.', 7),
    ('601cbca3-6dda-5257-a091-41f91f5d648a'::uuid, '260031d5-2c4d-5f47-a033-5366020445ad'::uuid, 'Comment traduit-on « pendant la réunion » ?', 'mcq', '["During the meeting","While the meeting","For the meeting","Since the meeting"]'::jsonb, 0, 'Un nom appelle *during*.', 8),
    ('9ec4fb61-a7ac-5b7c-a849-7d7e80908d9c'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, 'Quelle forme est correcte ?', 'mcq', '["Because of the rain","Because of it was raining","Because the rain","Due to it rained"]'::jsonb, 0, '*Because of* est suivi d’un groupe nominal.', 1),
    ('19de0ec4-fc7c-5865-a1fc-58d58d19bc81'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, '« I came for help you » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le but devant un verbe se dit *to help*, jamais *for to*.', 2),
    ('ec960a83-f031-5cad-bbf3-72320c5bff0a'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, '« So that » s’emploie surtout quand…', 'mcq', '["Le sujet du but est différent","Le sujet est le même","La cause est connue","On exprime une conséquence datée"]'::jsonb, 0, '*He spoke slowly so that everyone could understand.*', 3),
    ('7913c0fa-2fd4-5dfb-a0fd-32fa86e7f6e7'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, '« As it was late, we left » exprime une cause.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*As* et *since* introduisent une cause souvent déjà connue.', 4),
    ('9aa49cae-ec96-5517-a785-b9d96c9c31b4'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, 'Comment dit-on « afin de ne pas être en retard » ?', 'mcq', '["So as not to be late","So as to not be late","For not being late","To not be late"]'::jsonb, 0, 'La négation se place devant *to* dans cette structure.', 5),
    ('4e9214f5-ee7a-52c5-a569-1bb3b61051d3'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, '« Thanks to » introduit une cause négative.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’emploie pour une cause positive ; sinon *because of*, *owing to*.', 6),
    ('7ee7f6f1-6264-5a6d-8c6f-5b4a7f5b7d0a'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, 'Après « because », on attend…', 'mcq', '["Une proposition avec sujet et verbe","Un groupe nominal","Un infinitif","Un gérondif"]'::jsonb, 0, '*Because it was raining.*', 7),
    ('a3c714a2-803e-54f5-afce-4a4c4fd4c46f'::uuid, 'b6db826d-2b57-5b4f-8b02-6c36d7632be6'::uuid, '« In order to » est plus formel que « to » seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Même sens, registre plus soutenu.', 8),
    ('dacfd6f0-788f-5db3-b65d-899bc9369a90'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« Unless you hurry » signifie…', 'mcq', '["Si tu ne te dépêches pas","Si tu te dépêches","Bien que tu te dépêches","Pendant que tu te dépêches"]'::jsonb, 0, '*Unless* contient déjà la négation.', 1),
    ('348d4986-f118-58cb-9bf9-ec8165f47b42'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« Despite he was tired » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Despite* est une préposition : *despite being tired* ou *although he was tired*.', 2),
    ('73a24ec9-0022-557f-ba1b-fcd4a7d2deb0'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, 'Quelle structure suit « in spite of » ?', 'mcq', '["Un nom ou un -ING","Une proposition complète","Un infinitif","Un modal"]'::jsonb, 0, 'Comme *despite*.', 3),
    ('444214ab-f96e-59c2-9100-8a4189a7a977'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« Whereas » exprime…', 'mcq', '["Une opposition entre deux faits","Une condition","Une cause","Un but"]'::jsonb, 0, '*He likes tea, whereas she prefers coffee.*', 4),
    ('ce03bb34-b20b-5c37-b3a2-14374d4535d5'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« If I had money, I would travel » relève de l’irréel du présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Type 2 : prétérit dans la subordonnée, *would* dans la principale.', 5),
    ('823051f1-3384-5309-bcfc-659656897dae'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« Although » introduit une proposition complète.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec sujet et verbe conjugué.', 6),
    ('1fed8ef9-313f-51a4-91eb-6bcdf8b6f413'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« In case it rains » signifie…', 'mcq', '["Au cas où il pleuvrait","S’il pleut, alors","Bien qu’il pleuve","Puisqu’il pleut"]'::jsonb, 0, 'La précaution prise par avance.', 7),
    ('760acd75-a148-545b-97a0-3f0a12d0e6b3'::uuid, 'ea2d6ce6-5447-58db-a4e3-601613dcf646'::uuid, '« However » s’emploie pour…', 'mcq', '["Marquer une opposition entre deux phrases","Introduire une condition","Exprimer un but","Introduire une cause"]'::jsonb, 0, 'Souvent en tête de phrase, suivi d’une virgule.', 8),
    ('57399abd-3fd9-5444-b2ae-3ac04151f8b7'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, '« I used to smoke » signifie…', 'mcq', '["Je fumais autrefois, mais plus maintenant","J’ai l’habitude de fumer","Je me suis habitué à fumer","Je vais fumer"]'::jsonb, 0, '*Used to* implique toujours une rupture avec le présent.', 1),
    ('078776d1-9d13-54ed-b6de-187d88577a17'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, '« I’m used to getting up early » signifie…', 'mcq', '["J’ai l’habitude de me lever tôt","Je me levais tôt autrefois","Je vais me lever tôt","Je déteste me lever tôt"]'::jsonb, 0, 'Ici *to* est une préposition, d’où le -ING.', 2),
    ('9479feb8-5e20-56f6-a078-fab67a6583b7'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, '« I would live in York » est correct pour une habitude passée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Would* ne s’emploie pas pour un état : *I used to live in York*.', 3),
    ('deca4126-a47f-517d-8a85-99c2fb3aabf5'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, 'La négation de « used to » est…', 'mcq', '["I didn’t use to","I didn’t used to","I usen’t to","I not used to"]'::jsonb, 0, '*Did* porte le passé, donc *use* sans -d.', 4),
    ('be6a7b80-7a43-503a-87ec-17b1d82757d6'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, '« Every summer, we would go to the seaside » évoque une habitude passée répétée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Valeur fréquentative de *would* dans un récit.', 5),
    ('7f14c271-097b-5884-917a-f323f662298a'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, '« Get used to » signifie…', 'mcq', '["S’habituer progressivement","Avoir toujours été habitué","Perdre une habitude","Refuser une habitude"]'::jsonb, 0, '*You’ll get used to it.*', 6),
    ('1d2ed5e4-e81e-57a8-a4c1-4bd78755b872'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, 'L’habitude au présent se rend par…', 'mcq', '["Le présent simple + adverbe de fréquence","used to + base verbale","would + base verbale","be + -ing"]'::jsonb, 0, '*I usually walk to school.*', 7),
    ('b8fba261-433a-56ce-8974-db89d5eee22d'::uuid, '4989a1c2-9674-51e3-bde1-17be5e1fc9c4'::uuid, 'Après « be used to », on emploie la base verbale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie la forme en -ING : *used to getting up*.', 8),
    ('18065511-c05a-51f5-ac41-7c42cfabd279'::uuid, 'b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, 'Quelle construction suit « make » à l’actif ?', 'mcq', '["make + complément + base verbale","make + complément + to + base verbale","make + -ing","make + participe passé"]'::jsonb, 0, '*She made me wait.*', 1),
    ('e0c10f30-bcf6-59aa-8d10-8c17560db2a1'::uuid, 'b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, '« I was made to wait » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Au passif, *make* retrouve le *to*.', 2),
    ('5aebc128-b039-568d-ac68-a28357189e4d'::uuid, 'b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, 'Lequel se construit avec « to » ?', 'mcq', '["get","make","have","let"]'::jsonb, 0, '*I got him to help me.*', 3),
    ('f6be8fd2-2793-593b-b285-c7a954b40a3d'::uuid, 'b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, '« I had my hair cut » signifie…', 'mcq', '["Je me suis fait couper les cheveux","J’ai coupé mes cheveux moi-même","J’avais les cheveux coupés courts","Je voulais couper mes cheveux"]'::jsonb, 0, 'La structure *have something done* désigne l’action d’un tiers.', 4),
    ('a9dcbdcf-9234-5aa0-be37-c1545a398fbe'::uuid, 'b5ffba57-052e-5c6d-9524-7109a133e495'::uuid, '« Let » exprime la permission.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Let me explain*, *they let him go*.', 5),
